// Manchester encoder module
module manchester_encoder #(
    parameter N = 8  // Default width of input data
) (
    input  logic clk_in,          // Clock input
    input  logic rst_in,          // Active high reset input
    input  logic enc_valid_in,        // Input valid signal
    input  logic [N-1:0] enc_data_in, // N-bit input data
    output logic enc_valid_out,       // Output valid signal
    output logic [2*N-1:0] enc_data_out // 2N-bit output encoded data
);

    // Internal register to hold the encoded data


    // Combinational logic to generate Manchester encoded data
    always_comb begin
        enc_data_out = '0;
        enc_valid_out = 1'b0;
        if (enc_valid_in && !rst_in) begin
            for (int i = 0; i < N; i++) begin
                if (enc_data_in[i] == 1'b1) begin
                    enc_data_out[2*i] = 1'b1;
                    enc_data_out[2*i + 1] = 1'b0;
                end else begin
                    enc_data_out[2*i] = 1'b0;
                    enc_data_out[2*i + 1] = 1'b1;
                end
            end
            enc_valid_out = 1'b1; // Set the valid signal
        end else begin
            enc_valid_out = 1'b0; // Clear the valid signal if no valid input
        end
    end

endmodule

module pipeline_mac #(parameter DWIDTH=16,N=4)(input clk,rstn,input [DWIDTH-1:0] multiplicand,multiplier,input valid_i,output reg [2*DWIDTH+$clog2(N)-1:0] result,output reg valid_out);
localparam DWIDTH_ACCUMULATOR=2*DWIDTH+$clog2(N);
localparam AW=DWIDTH_ACCUMULATOR;
reg [2*DWIDTH-1:0] product;reg product_valid;reg [AW-1:0] acc;integer count;
always @(posedge clk or negedge rstn)begin
 if(!rstn)begin product<=0;product_valid<=0;acc<=0;count<=0;result<=0;valid_out<=0;end
 else begin
 product_valid<=valid_i;if(valid_i)product<=multiplicand*multiplier;
 valid_out<=0;
 if(product_valid)begin
 if(count==N-1)begin result<=acc+product;valid_out<=1;count<=0;acc<=0;end
 else begin acc<=acc+product;count<=count+1;end
 end
 end
end
endmodule

module spi_fsm(input i_clk,i_rst_b,input [15:0] i_data_in,input i_enable,i_fault,i_clear,output reg o_spi_cs_b,o_spi_clk,o_spi_data,output reg [4:0] o_bits_left,output reg o_done,output reg [1:0] o_fsm_state);
reg [15:0] data_q;
always @(posedge i_clk or negedge i_rst_b)begin
 if(!i_rst_b)begin o_fsm_state<=0;o_spi_cs_b<=1;o_spi_clk<=0;o_spi_data<=0;o_bits_left<=16;o_done<=0;data_q<=0;end
 else begin
 o_done<=0;
 if(i_clear || !i_enable)begin o_fsm_state<=0;o_spi_cs_b<=1;o_spi_clk<=0;o_spi_data<=0;o_bits_left<=16;end
 else if(i_fault || o_fsm_state==3)begin o_done<=o_fsm_state!=3;o_fsm_state<=3;o_spi_cs_b<=1;o_spi_clk<=0;o_spi_data<=0;o_bits_left<=16;end
 else case(o_fsm_state)
 0:begin data_q<=i_data_in;o_bits_left<=16;o_spi_cs_b<=0;o_spi_clk<=0;o_spi_data<=0;o_fsm_state<=1;end
 1:begin o_spi_cs_b<=0;o_spi_clk<=0;o_spi_data<=data_q[15];o_fsm_state<=2;end
 2:begin o_spi_clk<=1;data_q<=data_q<<1;o_bits_left<=o_bits_left-1'b1;
 if(o_bits_left==1)begin o_done<=1;o_fsm_state<=0;end else o_fsm_state<=1;end
 default:o_fsm_state<=0;
 endcase
 end
end
endmodule

module fifo_async #(parameter DATA_WIDTH=8,DEPTH=16)(input w_clk,w_rst,w_inc,input [DATA_WIDTH-1:0] w_data,input r_clk,r_rst,r_inc,output w_full,r_empty,output reg [DATA_WIDTH-1:0] r_data);
localparam AW=$clog2(DEPTH);
reg [DATA_WIDTH-1:0] mem[0:DEPTH-1];
reg [AW:0] wb,rb,wg,rg,rs1,rs2,ws1,ws2;
wire [AW:0] wn=wb+{{AW{1'b0}},(w_inc&&!w_full)};
wire [AW:0] rn=rb+{{AW{1'b0}},(r_inc&&!r_empty)};
wire [AW:0] rbin;
genvar j;generate for(j=0;j<=AW;j=j+1)begin assign rbin[j]=^(rs2>>j);end endgenerate
assign w_full=(wb[AW]!=rbin[AW]) && (wb[AW-1:0]==rbin[AW-1:0]);
assign r_empty=rg==ws2;
always @(posedge w_clk or posedge w_rst)if(w_rst)begin wb<=0;wg<=0;rs1<=0;rs2<=0;end
else begin rs1<=rg;rs2<=rs1;wb<=wn;wg<=(wn>>1)^wn;if(w_inc&&!w_full)mem[wb[AW-1:0]]<=w_data;end
always @(posedge r_clk or posedge r_rst)if(r_rst)begin rb<=0;rg<=0;ws1<=0;ws2<=0;r_data<=0;end
else begin ws1<=wg;ws2<=ws1;rb<=rn;rg<=(rn>>1)^rn;if(r_inc&&!r_empty)r_data<=mem[rb[AW-1:0]];end
endmodule
